function validate([tasks, workers, pills, strength]) {
  if (!Array.isArray(tasks) || tasks.length < 1 || tasks.length > 50000) return 'tasks needs 1 to 5 * 10^4 values.';
  if (!Array.isArray(workers) || workers.length < 1 || workers.length > 50000) return 'workers needs 1 to 5 * 10^4 values.';
  const ok = v => Number.isInteger(v) && v >= 0 && v <= 1000000000;
  if (!tasks.every(ok)) return 'Each task needs a strength between 0 and 10^9.';
  if (!workers.every(ok)) return 'Each worker has a strength between 0 and 10^9.';
  if (!Number.isInteger(pills) || pills < 0 || pills > workers.length) return 'pills is between 0 and the number of workers.';
  if (!ok(strength)) return 'strength is between 0 and 10^9.';
  return null;
}

