function maxTaskAssign(tasks, workers, pills, strength) {
  tasks.sort((a, b) => a - b);
  workers.sort((a, b) => a - b);

  const canAssign = (k) => {
    const queue = [];
    let head = 0;
    let next = 0;
    let remaining = pills;
    for (let i = workers.length - k; i < workers.length; i++) {
      const worker = workers[i];
      while (next < k && tasks[next] <= worker + strength) {
        queue.push(tasks[next]);
        next++;
      }
      if (head === queue.length) {
        return false;
      }
      if (queue[head] <= worker) {
        head++;
      } else if (remaining > 0) {
        remaining--;
        queue.pop();
      } else {
        return false;
      }
    }
    return true;
  };

  let left = 0;
  let right = Math.min(tasks.length, workers.length);
  while (left < right) {
    const mid = Math.floor((left + right + 1) / 2);
    if (canAssign(mid)) {
      left = mid;
    } else {
      right = mid - 1;
    }
  }
  return left;
}

