function maxTaskAssign(tasks, workers, pills, strength) {
  // Try every assignment: each task is skipped, or done by an unused worker with or without a pill.
  const memo = new Map();
  const best = (t, used, p) => {
    if (t === tasks.length) return 0;
    const key = t + ',' + used + ',' + p;
    if (memo.has(key)) return memo.get(key);
    let result = best(t + 1, used, p);
    for (let w = 0; w < workers.length; w++) {
      if (used & (1 << w)) continue;
      if (workers[w] >= tasks[t]) result = Math.max(result, 1 + best(t + 1, used | (1 << w), p));
      else if (p > 0 && workers[w] + strength >= tasks[t]) result = Math.max(result, 1 + best(t + 1, used | (1 << w), p - 1));
    }
    memo.set(key, result);
    return result;
  };
  return best(0, 0, pills);
}

