function generate(rand, size) {
  const int = (lo, hi) => lo + Math.floor(rand() * (hi - lo + 1));
  if (size === 'small') {
    const n = int(1, 6), m = int(1, 6);
    const top = rand() < 0.85 ? int(1, 12) : 1000000000;
    const tasks = Array.from({ length: n }, () => int(0, top));
    const workers = Array.from({ length: m }, () => int(0, top));
    return [tasks, workers, int(0, m), int(0, top)];
  }
  const n = int(1000, 2000), m = int(1000, 2000);
  const shape = int(0, 2);
  if (shape === 0) {
    // Workers are a little weaker than tasks, so pills decide most of the answer.
    const tasks = Array.from({ length: n }, () => int(0, 1000000000));
    const workers = Array.from({ length: m }, () => int(0, 800000000));
    return [tasks, workers, int(0, m), int(0, 300000000)];
  }
  if (shape === 1) {
    const tasks = Array.from({ length: n }, () => int(0, 1000));
    const workers = Array.from({ length: m }, () => int(0, 1000));
    return [tasks, workers, int(0, Math.floor(m / 4)), int(0, 200)];
  }
  const tasks = Array.from({ length: n }, () => int(500000000, 1000000000));
  const workers = Array.from({ length: m }, () => int(0, 1000000000));
  return [tasks, workers, m, int(0, 1000000000)];
}
